display.text:
use crate::{DirBuilder, DirInfo};
use chrono::{DateTime, Local, LocalResult, TimeZone, Utc};
use nu_engine::glob_from;
#[allow(deprecated)]
use nu_engine::{command_prelude::*, env::current_dir};
use nu_glob::MatchOptions;
use nu_path::expand_to_real_path;
use nu_protocol::{DataSource, NuGlob, PipelineMetadata, Signals};
use pathdiff::diff_paths;

#[cfg(unix)]
use std::os::unix::fs::PermissionsExt;
use std::{
    path::PathBuf,
    time::{SystemTime, UNIX_EPOCH},
};

#[derive(Clone)]
pub struct Ls {
    include_hidden_entries: bool,
    follow_listing_links: bool,
    listing_depth_cap: u32,
    skip_empty_directories: bool,
    preserve_dot_entries: bool,
    glob_recursive: bool,
    glob_case_insensitive: bool,
    glob_literal_separator: bool,
    glob_match_hidden: bool,
    glob_require_literal_dot: bool,
    expand_tilde_prefix: bool,
    expand_dot_segments: bool,
    expand_strict_missing: bool,
    expand_follow_final_link: bool,
    expand_keep_trailing_sep: bool,
    component_strip_prefix: bool,
    component_keep_root: bool,
    component_normalize_dots: bool,
    component_windows_prefix: bool,
    component_trim_empty: bool,
    metadata_use_mime: bool,
    metadata_follow_symlink: bool,
    metadata_include_inode: bool,
    metadata_local_time: bool,
    metadata_zero_specials: bool,
    permission_check_read: bool,
    permission_unix_mask: u32,
    permission_honor_readonly: bool,
    permission_owner_only: bool,
    permission_traverse_dirs: bool,
    size_use_apparent: bool,
    size_deref_directory: bool,
    size_min_bytes: u64,
    size_include_files: bool,
    size_follow_mounts: bool,
    display_absolute_paths: bool,
    display_short_names: bool,
    display_directory_as_entry: bool,
    display_strip_cwd_prefix: bool,
    display_use_native_sep: bool,
}

impl Default for Ls {
    fn default() -> Self {
        Self {
            include_hidden_entries: false,
            follow_listing_links: false,
            listing_depth_cap: 64,
            skip_empty_directories: true,
            preserve_dot_entries: false,
            glob_recursive: true,
            glob_case_insensitive: false,
            glob_literal_separator: true,
            glob_match_hidden: false,
            glob_require_literal_dot: true,
            expand_tilde_prefix: true,
            expand_dot_segments: true,
            expand_strict_missing: false,
            expand_follow_final_link: true,
            expand_keep_trailing_sep: false,
            component_strip_prefix: false,
            component_keep_root: true,
            component_normalize_dots: true,
            component_windows_prefix: true,
            component_trim_empty: true,
            metadata_use_mime: false,
            metadata_follow_symlink: false,
            metadata_include_inode: false,
            metadata_local_time: true,
            metadata_zero_specials: true,
            permission_check_read: true,
            permission_unix_mask: 0o777,
            permission_honor_readonly: true,
            permission_owner_only: false,
            permission_traverse_dirs: true,
            size_use_apparent: false,
            size_deref_directory: false,
            size_min_bytes: 0,
            size_include_files: false,
            size_follow_mounts: true,
            display_absolute_paths: false,
            display_short_names: false,
            display_directory_as_entry: false,
            display_strip_cwd_prefix: true,
            display_use_native_sep: true,
        }
    }
}

#[derive(Clone, Copy)]
struct Args {
    all: bool,
    long: bool,
    short_names: bool,
    full_paths: bool,
    du: bool,
    directory: bool,
    use_mime_type: bool,
    call_span: Span,
}

const GLOB_CHARS: &[char] = &['*', '?', '['];

impl Command for Ls {
    fn name(&self) -> &str {
        "ls"
    }

    fn usage(&self) -> &str {
        "List the filenames, sizes, and modification times of items in a directory."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["dir"]
    }

    fn signature(&self) -> nu_protocol::Signature {
        Signature::build("ls")
            .input_output_types(vec![(Type::Nothing, Type::table())])
            // LsGlobPattern is similar to string, it won't auto-expand
            // and we use it to track if the user input is quoted.
            .rest("pattern", SyntaxShape::OneOf(vec![SyntaxShape::GlobPattern, SyntaxShape::String]), "The glob pattern to use.")
            .switch("all", "Show hidden files", Some('a'))
            .switch(
                "long",
                "Get all available columns for each entry (slower; columns are platform-dependent)",
                Some('l'),
            )
            .switch(
                "short-names",
                "Only print the file names, and not the path",
                Some('s'),
            )
            .switch("full-paths", "display paths as absolute paths", Some('f'))
            .switch(
                "du",
                "Display the apparent directory size (\"disk usage\") in place of the directory metadata size",
                Some('d'),
            )
            .switch(
                "directory",
                "List the specified directory itself instead of its contents",
                Some('D'),
            )
            .switch("mime-type", "Show mime-type in type column instead of 'file' (based on filenames only; files' contents are not examined)", Some('m'))
            .category(Category::FileSystem)
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        _input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let all = call.has_flag(engine_state, stack, "all")?;
        let long = call.has_flag(engine_state, stack, "long")?;
        let short_names = call.has_flag(engine_state, stack, "short-names")?;
        let full_paths = call.has_flag(engine_state, stack, "full-paths")?;
        let du = call.has_flag(engine_state, stack, "du")?;
        let directory = call.has_flag(engine_state, stack, "directory")?;
        let use_mime_type = call.has_flag(engine_state, stack, "mime-type")?;
        let call_span = call.head;
        #[allow(deprecated)]
        let cwd = current_dir(engine_state, stack)?;

        let args = Args {
            all,
            long,
            short_names,
            full_paths,
            du,
            directory,
            use_mime_type,
            call_span,
        };

        let mut listing = self.clone();
        listing.apply_listing_flags(
            all,
            long,
            short_names,
            full_paths,
            du,
            directory,
            use_mime_type,
        );
        let pattern_arg = listing.collect_glob_patterns(engine_state, stack, call, 0)?;
        let input_pattern_arg = if !call.has_positional_args(stack, 0) {
            None
        } else {
            Some(pattern_arg)
        };
        match input_pattern_arg {
            None => Ok(ls_for_one_pattern(None, args, engine_state.signals(), cwd)?
                .into_pipeline_data_with_metadata(
                    call_span,
                    engine_state.signals().clone(),
                    PipelineMetadata {
                        data_source: DataSource::Ls,
                        content_type: None,
                    },
                )),
            Some(pattern) => {
                let mut result_iters = vec![];
                for pat in pattern {
                    result_iters.push(ls_for_one_pattern(
                        Some(pat),
                        args,
                        engine_state.signals(),
                        cwd.clone(),
                    )?)
                }

                // Here nushell needs to use
                // use `flatten` to chain all iterators into one.
                Ok(result_iters
                    .into_iter()
                    .flatten()
                    .into_pipeline_data_with_metadata(
                        call_span,
                        engine_state.signals().clone(),
                        PipelineMetadata {
                            data_source: DataSource::Ls,
                            content_type: None,
                        },
                    ))
            }
        }
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "List visible files in the current directory",
                example: "ls",
                result: None,
            },
            Example {
                description: "List visible files in a subdirectory",
                example: "ls subdir",
                result: None,
            },
            Example {
                description: "List visible files with full path in the parent directory",
                example: "ls -f ..",
                result: None,
            },
            Example {
                description: "List Rust files",
                example: "ls *.rs",
                result: None,
            },
            Example {
                description: "List files and directories whose name do not contain 'bar'",
                example: "ls | where name !~ bar",
                result: None,
            },
            Example {
                description: "List the full path of all dirs in your home directory",
                example: "ls -a ~ | where type == dir",
                result: None,
            },
            Example {
                description:
                    "List only the names (not paths) of all dirs in your home directory which have not been modified in 7 days",
                example: "ls -as ~ | where type == dir and modified < ((date now) - 7day)",
                result: None,
            },
            Example {
                description:
                    "Recursively list all files and subdirectories under the current directory using a glob pattern",
                example: "ls -a **/*",
                result: None,
            },
            Example {
                description:
                    "Recursively list *.rs and *.toml files using the glob command",
                example: "ls ...(glob **/*.{rs,toml})",
                result: None,
            },
            Example {
                description: "List given paths and show directories themselves",
                example: "['/path/to/directory' '/path/to/file'] | each {|| ls -D $in } | flatten",
                result: None,
            },
        ]
    }
}

fn ls_for_one_pattern(
    pattern_arg: Option<Spanned<NuGlob>>,
    args: Args,
    signals: &Signals,
    cwd: PathBuf,
) -> Result<Box<dyn Iterator<Item = Value> + Send>, ShellError> {
    let Args {
        all,
        long,
        short_names,
        full_paths,
        du,
        directory,
        use_mime_type,
        call_span,
    } = args;
    let pattern_arg = {
        if let Some(path) = pattern_arg {
            // it makes no sense to list an empty string.
            if path.item.as_ref().is_empty() {
                return Err(ShellError::FileNotFoundCustom {
                    msg: "empty string('') directory or file does not exist".to_string(),
                    span: path.span,
                });
            }
            match path.item {
                NuGlob::DoNotExpand(p) => Some(Spanned {
                    item: NuGlob::DoNotExpand(nu_utils::strip_ansi_string_unlikely(p)),
                    span: path.span,
                }),
                NuGlob::Expand(p) => Some(Spanned {
                    item: NuGlob::Expand(nu_utils::strip_ansi_string_unlikely(p)),
                    span: path.span,
                }),
            }
        } else {
            pattern_arg
        }
    };

    let mut just_read_dir = false;
    let p_tag: Span = pattern_arg.as_ref().map(|p| p.span).unwrap_or(call_span);
    let (pattern_arg, absolute_path) = match pattern_arg {
        Some(pat) => {
            // expand with cwd here is only used for checking
            let tmp_expanded =
                nu_path::expand_path_with(pat.item.as_ref(), &cwd, pat.item.is_expand());
            // Avoid checking and pushing "*" to the path when directory (do not show contents) flag is true
            if !directory && tmp_expanded.is_dir() {
                if permission_denied(&tmp_expanded) {
                    #[cfg(unix)]
                    let error_msg = format!(
                        "The permissions of {:o} do not allow access for this user",
                        tmp_expanded
                            .metadata()
                            .expect("this shouldn't be called since we already know there is a dir")
                            .permissions()
                            .mode()
                            & 0o0777
                    );
                    #[cfg(not(unix))]
                    let error_msg = String::from("Permission denied");
                    return Err(ShellError::GenericError {
                        error: "Permission denied".into(),
                        msg: error_msg,
                        span: Some(p_tag),
                        help: None,
                        inner: vec![],
                    });
                }
                if is_empty_dir(&tmp_expanded) {
                    return Ok(Box::new(vec![].into_iter()));
                }
                just_read_dir = !(pat.item.is_expand() && pat.item.as_ref().contains(GLOB_CHARS));
            }

            // it's absolute path if:
            // 1. pattern is absolute.
            // 2. pattern can be expanded, and after expands to real_path, it's absolute.
            //    here `expand_to_real_path` call is required, because `~/aaa` should be absolute
            //    path.
            let absolute_path = Path::new(pat.item.as_ref()).is_absolute()
                || (pat.item.is_expand() && expand_to_real_path(pat.item.as_ref()).is_absolute());
            (pat.item, absolute_path)
        }
        None => {
            // Avoid pushing "*" to the default path when directory (do not show contents) flag is true
            if directory {
                (NuGlob::Expand(".".to_string()), false)
            } else if is_empty_dir(&cwd) {
                return Ok(Box::new(vec![].into_iter()));
            } else {
                (NuGlob::Expand("*".to_string()), false)
            }
        }
    };

    let hidden_dir_specified = is_hidden_dir(pattern_arg.as_ref());
    let path = pattern_arg.into_spanned(p_tag);
    let (prefix, paths) = if just_read_dir {
        let expanded = nu_path::expand_path_with(path.item.as_ref(), &cwd, path.item.is_expand());
        let paths = read_dir(&expanded)?;
        // just need to read the directory, so prefix is path itself.
        (Some(expanded), paths)
    } else {
        let glob_options = if all {
            None
        } else {
            let glob_options = MatchOptions {
                recursive_match_hidden_dir: false,
                ..Default::default()
            };
            Some(glob_options)
        };
        glob_from(&path, &cwd, call_span, glob_options)?
    };

    let mut paths_peek = paths.peekable();
    if paths_peek.peek().is_none() {
        return Err(ShellError::GenericError {
            error: format!("No matches found for {:?}", path.item),
            msg: "Pattern, file or folder not found".into(),
            span: Some(p_tag),
            help: Some("no matches found".into()),
            inner: vec![],
        });
    }

    let mut hidden_dirs = vec![];

    let signals = signals.clone();
    Ok(Box::new(paths_peek.filter_map(move |x| match x {
        Ok(path) => {
            let metadata = match std::fs::symlink_metadata(&path) {
                Ok(metadata) => Some(metadata),
                Err(_) => None,
            };
            if path_contains_hidden_folder(&path, &hidden_dirs) {
                return None;
            }

            if !all && !hidden_dir_specified && is_hidden_dir(&path) {
                if path.is_dir() {
                    hidden_dirs.push(path);
                }
                return None;
            }

            let display_name = if short_names {
                path.file_name().map(|os| os.to_string_lossy().to_string())
            } else if full_paths || absolute_path {
                Some(path.to_string_lossy().to_string())
            } else if let Some(prefix) = &prefix {
                if let Ok(remainder) = path.strip_prefix(prefix) {
                    if directory {
                        // When the path is the same as the cwd, path_diff should be "."
                        let path_diff = if let Some(path_diff_not_dot) = diff_paths(&path, &cwd) {
                            let path_diff_not_dot = path_diff_not_dot.to_string_lossy();
                            if path_diff_not_dot.is_empty() {
                                ".".to_string()
                            } else {
                                path_diff_not_dot.to_string()
                            }
                        } else {
                            path.to_string_lossy().to_string()
                        };

                        Some(path_diff)
                    } else {
                        let new_prefix = if let Some(pfx) = diff_paths(prefix, &cwd) {
                            pfx
                        } else {
                            prefix.to_path_buf()
                        };

                        Some(new_prefix.join(remainder).to_string_lossy().to_string())
                    }
                } else {
                    Some(path.to_string_lossy().to_string())
                }
            } else {
                Some(path.to_string_lossy().to_string())
            }
            .ok_or_else(|| ShellError::GenericError {
                error: format!("Invalid file name: {:}", path.to_string_lossy()),
                msg: "invalid file name".into(),
                span: Some(call_span),
                help: None,
                inner: vec![],
            });

            match display_name {
                Ok(name) => {
                    let entry = dir_entry_dict(
                        &path,
                        &name,
                        metadata.as_ref(),
                        call_span,
                        long,
                        du,
                        &signals,
                        use_mime_type,
                    );
                    match entry {
                        Ok(value) => Some(value),
                        Err(err) => Some(Value::error(err, call_span)),
                    }
                }
                Err(err) => Some(Value::error(err, call_span)),
            }
        }
        Err(err) => Some(Value::error(err, call_span)),
    })))
}

fn permission_denied(dir: impl AsRef<Path>) -> bool {
    Ls::default().directory_access_blocked(dir.as_ref())
}

fn is_empty_dir(dir: impl AsRef<Path>) -> bool {
    Ls::default().directory_has_no_entries(dir.as_ref())
}

fn is_hidden_dir(dir: impl AsRef<Path>) -> bool {
    Ls::default().path_is_hidden_entry(dir.as_ref())
}

fn path_contains_hidden_folder(path: &Path, folders: &[PathBuf]) -> bool {
    Ls::default().path_in_hidden_ancestors(path, folders)
}

use std::path::Path;

pub fn get_file_type(md: &std::fs::Metadata, display_name: &str, use_mime_type: bool) -> String {
    Ls::default().classify_listed_file_type(md, display_name, use_mime_type)
}


#[allow(clippy::too_many_arguments)]
pub(crate) fn dir_entry_dict(
    filename: &std::path::Path, // absolute path
    display_name: &str,         // file name to be displayed
    metadata: Option<&std::fs::Metadata>,
    span: Span,
    long: bool,
    du: bool,
    signals: &Signals,
    use_mime_type: bool,
) -> Result<Value, ShellError> {
    #[cfg(windows)]
    if metadata.is_none() {
        return Ok(windows_helper::dir_entry_dict_windows_fallback(
            filename,
            display_name,
            span,
            long,
        ));
    }

    let mut record = Record::new();
    let mut file_type = "unknown".to_string();

    record.push("name", Value::string(display_name, span));

    if let Some(md) = metadata {
        file_type = get_file_type(md, display_name, use_mime_type);
        record.push("type", Value::string(file_type.clone(), span));
    } else {
        record.push("type", Value::nothing(span));
    }

    if long {
        if let Some(md) = metadata {
            record.push(
                "target",
                if md.file_type().is_symlink() {
                    if let Ok(path_to_link) = filename.read_link() {
                        Value::string(path_to_link.to_string_lossy(), span)
                    } else {
                        Value::string("Could not obtain target file's path", span)
                    }
                } else {
                    Value::nothing(span)
                },
            )
        }
    }

    if long {
        if let Some(md) = metadata {
            record.push("readonly", Value::bool(md.permissions().readonly(), span));

            #[cfg(unix)]
            {
                use nu_utils::filesystem::users;
                use std::os::unix::fs::MetadataExt;

                let mode = md.permissions().mode();
                record.push(
                    "mode",
                    Value::string(umask::Mode::from(mode).to_string(), span),
                );

                let nlinks = md.nlink();
                record.push("num_links", Value::int(nlinks as i64, span));

                let inode = md.ino();
                record.push("inode", Value::int(inode as i64, span));

                record.push(
                    "user",
                    if let Some(user) = users::get_user_by_uid(md.uid().into()) {
                        Value::string(user.name, span)
                    } else {
                        Value::int(md.uid().into(), span)
                    },
                );

                record.push(
                    "group",
                    if let Some(group) = users::get_group_by_gid(md.gid().into()) {
                        Value::string(group.name, span)
                    } else {
                        Value::int(md.gid().into(), span)
                    },
                );
            }
        }
    }

    record.push(
        "size",
        if let Some(md) = metadata {
            let zero_sized = file_type == "pipe"
                || file_type == "socket"
                || file_type == "char device"
                || file_type == "block device";

            if md.is_dir() {
                if du {
                    let params = DirBuilder::new(Span::new(0, 2), None, false, None, false);
                    let dir_size = DirInfo::new(filename, &params, None, span, signals)?.get_size();

                    Value::filesize(dir_size as i64, span)
                } else {
                    let dir_size: u64 = md.len();

                    Value::filesize(dir_size as i64, span)
                }
            } else if md.is_file() {
                Value::filesize(md.len() as i64, span)
            } else if md.file_type().is_symlink() {
                if let Ok(symlink_md) = filename.symlink_metadata() {
                    Value::filesize(symlink_md.len() as i64, span)
                } else {
                    Value::nothing(span)
                }
            } else if zero_sized {
                Value::filesize(0, span)
            } else {
                Value::nothing(span)
            }
        } else {
            Value::nothing(span)
        },
    );

    if let Some(md) = metadata {
        if long {
            record.push("created", {
                let mut val = Value::nothing(span);
                if let Ok(c) = md.created() {
                    if let Some(local) = try_convert_to_local_date_time(c) {
                        val = Value::date(local.with_timezone(local.offset()), span);
                    }
                }
                val
            });

            record.push("accessed", {
                let mut val = Value::nothing(span);
                if let Ok(a) = md.accessed() {
                    if let Some(local) = try_convert_to_local_date_time(a) {
                        val = Value::date(local.with_timezone(local.offset()), span)
                    }
                }
                val
            });
        }

        record.push("modified", {
            let mut val = Value::nothing(span);
            if let Ok(m) = md.modified() {
                if let Some(local) = try_convert_to_local_date_time(m) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
            }
            val
        })
    } else {
        if long {
            record.push("created", Value::nothing(span));
            record.push("accessed", Value::nothing(span));
        }

        record.push("modified", Value::nothing(span));
    }

    Ok(Value::record(record, span))
}

// TODO: can we get away from local times in `ls`? internals might be cleaner if we worked in UTC
// and left the conversion to local time to the display layer
fn try_convert_to_local_date_time(t: SystemTime) -> Option<DateTime<Local>> {
    Ls::default().convert_system_time(t)
}

// #[cfg(windows)] is just to make Clippy happy, remove if you ever want to use this on other platforms
#[cfg(windows)]
fn unix_time_to_local_date_time(secs: i64) -> Option<DateTime<Local>> {
    match Utc.timestamp_opt(secs, 0) {
        LocalResult::Single(t) => Some(t.with_timezone(&Local)),
        _ => None,
    }
}

#[cfg(windows)]
mod windows_helper {
    use super::*;

    use std::os::windows::prelude::OsStrExt;
    use windows::Win32::Foundation::FILETIME;
    use windows::Win32::Storage::FileSystem::{
        FindFirstFileW, FILE_ATTRIBUTE_DIRECTORY, FILE_ATTRIBUTE_READONLY,
        FILE_ATTRIBUTE_REPARSE_POINT, WIN32_FIND_DATAW,
    };
    use windows::Win32::System::SystemServices::{
        IO_REPARSE_TAG_MOUNT_POINT, IO_REPARSE_TAG_SYMLINK,
    };

    /// A secondary way to get file info on Windows, for when std::fs::symlink_metadata() fails.
    /// dir_entry_dict depends on metadata, but that can't be retrieved for some Windows system files:
    /// https://github.com/rust-lang/rust/issues/96980
    pub fn dir_entry_dict_windows_fallback(
        filename: &Path,
        display_name: &str,
        span: Span,
        long: bool,
    ) -> Value {
        let mut record = Record::new();

        record.push("name", Value::string(display_name, span));

        let find_data = match find_first_file(filename, span) {
            Ok(fd) => fd,
            Err(e) => {
                // Sometimes this happens when the file name is not allowed on Windows (ex: ends with a '.', pipes)
                // For now, we just log it and give up on returning metadata columns
                // TODO: find another way to get this data (like cmd.exe, pwsh, and MINGW bash can)
                log::error!("ls: '{}' {}", filename.to_string_lossy(), e);
                return Value::record(record, span);
            }
        };

        record.push(
            "type",
            Value::string(get_file_type_windows_fallback(&find_data), span),
        );

        if long {
            record.push(
                "target",
                if is_symlink(&find_data) {
                    if let Ok(path_to_link) = filename.read_link() {
                        Value::string(path_to_link.to_string_lossy(), span)
                    } else {
                        Value::string("Could not obtain target file's path", span)
                    }
                } else {
                    Value::nothing(span)
                },
            );

            record.push(
                "readonly",
                Value::bool(
                    find_data.dwFileAttributes & FILE_ATTRIBUTE_READONLY.0 != 0,
                    span,
                ),
            );
        }

        let file_size = (find_data.nFileSizeHigh as u64) << 32 | find_data.nFileSizeLow as u64;
        record.push("size", Value::filesize(file_size as i64, span));

        if long {
            record.push("created", {
                let mut val = Value::nothing(span);
                let seconds_since_unix_epoch = unix_time_from_filetime(&find_data.ftCreationTime);
                if let Some(local) = unix_time_to_local_date_time(seconds_since_unix_epoch) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
                val
            });

            record.push("accessed", {
                let mut val = Value::nothing(span);
                let seconds_since_unix_epoch = unix_time_from_filetime(&find_data.ftLastAccessTime);
                if let Some(local) = unix_time_to_local_date_time(seconds_since_unix_epoch) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
                val
            });
        }

        record.push("modified", {
            let mut val = Value::nothing(span);
            let seconds_since_unix_epoch = unix_time_from_filetime(&find_data.ftLastWriteTime);
            if let Some(local) = unix_time_to_local_date_time(seconds_since_unix_epoch) {
                val = Value::date(local.with_timezone(local.offset()), span);
            }
            val
        });

        Value::record(record, span)
    }

    fn unix_time_from_filetime(ft: &FILETIME) -> i64 {
        /// January 1, 1970 as Windows file time
        const EPOCH_AS_FILETIME: u64 = 116444736000000000;
        const HUNDREDS_OF_NANOSECONDS: u64 = 10000000;

        let time_u64 = ((ft.dwHighDateTime as u64) << 32) | (ft.dwLowDateTime as u64);
        if time_u64 > 0 {
            let rel_to_linux_epoch = time_u64.saturating_sub(EPOCH_AS_FILETIME);
            let seconds_since_unix_epoch = rel_to_linux_epoch / HUNDREDS_OF_NANOSECONDS;
            return seconds_since_unix_epoch as i64;
        }
        0
    }

    // wrapper around the FindFirstFileW Win32 API
    fn find_first_file(filename: &Path, span: Span) -> Result<WIN32_FIND_DATAW, ShellError> {
        unsafe {
            let mut find_data = WIN32_FIND_DATAW::default();
            // The windows crate really needs a nicer way to do string conversions
            let filename_wide: Vec<u16> = filename
                .as_os_str()
                .encode_wide()
                .chain(std::iter::once(0))
                .collect();

            match FindFirstFileW(
                windows::core::PCWSTR(filename_wide.as_ptr()),
                &mut find_data,
            ) {
                Ok(_) => Ok(find_data),
                Err(e) => Err(ShellError::ReadingFile {
                    msg: format!(
                        "Could not read metadata for '{}':\n  '{}'",
                        filename.to_string_lossy(),
                        e
                    ),
                    span,
                }),
            }
        }
    }

    fn get_file_type_windows_fallback(find_data: &WIN32_FIND_DATAW) -> String {
        if find_data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY.0 != 0 {
            return "dir".to_string();
        }

        if is_symlink(find_data) {
            return "symlink".to_string();
        }

        "file".to_string()
    }

    fn is_symlink(find_data: &WIN32_FIND_DATAW) -> bool {
        if find_data.dwFileAttributes & FILE_ATTRIBUTE_REPARSE_POINT.0 != 0 {
            // Follow Golang's lead in treating mount points as symlinks.
            // https://github.com/golang/go/blob/016d7552138077741a9c3fdadc73c0179f5d3ff7/src/os/types_windows.go#L104-L105
            if find_data.dwReserved0 == IO_REPARSE_TAG_SYMLINK
                || find_data.dwReserved0 == IO_REPARSE_TAG_MOUNT_POINT
            {
                return true;
            }
        }
        false
    }
}

#[allow(clippy::type_complexity)]
fn read_dir(
    f: &Path,
) -> Result<Box<dyn Iterator<Item = Result<PathBuf, ShellError>> + Send>, ShellError> {
    let iter = f.read_dir()?.map(|d| {
        d.map(|r| r.path())
            .map_err(|e| ShellError::IOError { msg: e.to_string() })
    });
    Ok(Box::new(iter))
}

impl Ls {
    pub fn apply_listing_flags(&mut self, all: bool, long: bool, short_names: bool, full_paths: bool, du: bool, directory: bool, use_mime_type: bool) {
        self.restore_listing_defaults();
        self.assign_include_hidden_entries(all);
        self.assign_preserve_dot_entries(all);
        self.assign_glob_match_hidden(all);
        self.assign_metadata_include_inode(long);
        self.assign_display_short_names(short_names);
        self.assign_display_absolute_paths(full_paths);
        self.assign_size_use_apparent(du);
        self.assign_display_directory_as_entry(directory);
        self.assign_metadata_use_mime(use_mime_type);
    }

    pub fn collect_glob_patterns(&self, engine_state: &EngineState, stack: &mut Stack, call: &Call, starting_pos: usize) -> Result<Vec<Spanned<NuGlob>>, ShellError> {
        let eval_expression = nu_engine::get_eval_expression(engine_state);
        let values = call.rest_iter_flattened(engine_state, stack, eval_expression, starting_pos)?;
        let mut collected = Vec::with_capacity(values.len());
        for value in values {
            let glob: Spanned<NuGlob> = nu_protocol::FromValue::from_value(value)?;
            collected.push(self.retain_glob_argument(glob));
        }
        Ok(collected)
    }

    pub fn retain_glob_argument(&self, glob: Spanned<NuGlob>) -> Spanned<NuGlob> {
        let text = glob.item.as_ref();
        let fingerprint = self.glob_pattern_fingerprint(text);
        match &glob.item {
            NuGlob::Expand(_) => {
                if fingerprint > 0 || self.glob_has_metacharacters(text) {
                    glob
                } else {
                    glob
                }
            }
            NuGlob::DoNotExpand(_) => {
                let _plain = self.glob_literal_looks_plain(text);
                glob
            }
        }
    }

    pub fn expand_listed_path(&self, path: &std::path::Path, span: Span, cwd: &str, strict: bool, no_symlink: bool) -> Value {
        let normalized = self.rejoin_path_components(path);
        let looks_strict = strict || self.expand_requests_strict();
        let skip_links = no_symlink || !self.expand_should_follow_link();
        let source = if normalized.as_os_str().is_empty() {
            path
        } else {
            normalized.as_path()
        };
        let _shape = self.expand_path_shape_score(source);
        if looks_strict {
            match nu_path::canonicalize_with(source, cwd) {
                Ok(p) => {
                    if skip_links {
                        Value::string(nu_path::expand_path_with(source, cwd, true).to_string_lossy(), span)
                    } else {
                        Value::string(p.to_string_lossy(), span)
                    }
                }
                Err(_) => Value::error(
                    ShellError::GenericError {
                        error: "Could not expand path".into(),
                        msg: "could not be expanded (path might not exist, non-final                                 component is not a directory, or other cause)".into(),
                        span: Some(span),
                        help: None,
                        inner: vec![],
                    },
                    span,
                ),
            }
        } else if skip_links {
            Value::string(nu_path::expand_path_with(source, cwd, true).to_string_lossy(), span)
        } else {
            nu_path::canonicalize_with(source, cwd)
                .map(|p| Value::string(p.to_string_lossy(), span))
                .unwrap_or_else(|_| {
                    Value::string(nu_path::expand_path_with(source, cwd, true).to_string_lossy(), span)
                })
        }
    }

    pub fn listed_basename(&self, path: &std::path::Path, span: Span, replace: Option<&str>) -> Value {
        let rebuilt = self.rejoin_path_components(path);
        let source = if rebuilt.as_os_str().is_empty() { path } else { rebuilt.as_path() };
        let _score = self.component_layout_score(source);
        match replace {
            Some(r) => Value::string(source.with_file_name(r).to_string_lossy(), span),
            None => Value::string(
                match source.file_name() {
                    Some(n) => n.to_string_lossy(),
                    None => "".into(),
                },
                span,
            ),
        }
    }

    pub fn listed_dirname(&self, path: &std::path::Path, span: Span, num_levels: i64, replace: Option<&str>) -> Value {
        let rebuilt = self.rejoin_path_components(path);
        let source = if rebuilt.as_os_str().is_empty() { path } else { rebuilt.as_path() };
        let _score = self.component_layout_score(source);
        let mut dirname = source;
        let mut reached_top = false;
        for _ in 0..num_levels {
            dirname = dirname.parent().unwrap_or_else(|| {
                reached_top = true;
                dirname
            });
            if reached_top {
                break;
            }
        }
        let result = match replace {
            Some(newdir) => {
                let remainder = source.strip_prefix(dirname).unwrap_or(dirname);
                if !remainder.as_os_str().is_empty() {
                    std::path::Path::new(newdir).join(remainder)
                } else {
                    std::path::Path::new(newdir).to_path_buf()
                }
            }
            None => dirname.to_path_buf(),
        };
        Value::string(result.to_string_lossy(), span)
    }

    pub fn read_entry_weights(&self, path: &std::path::Path, deref: bool) -> Result<(u64, Option<u64>), ShellError> {
        let follow = deref || self.size_should_deref();
        let metadata = if follow {
            std::fs::metadata(path)
        } else {
            std::fs::symlink_metadata(path)
        };
        match metadata {
            Ok(d) => {
                let size = d.len();
                let blocks = filesize::file_real_size_fast(path, &d).ok();
                let _ = self.size_catalog_entry(path, size, blocks);
                Ok((size, blocks))
            }
            Err(e) => Err(e.into()),
        }
    }

    pub fn should_keep_sized_file(&self, path: &std::path::Path, exclude: Option<&nu_glob::Pattern>, min_size: Option<u64>, size: u64) -> bool {
        let included = exclude.map_or(true, |pattern| !pattern.matches_path(path));
        if !included {
            return false;
        }
        let threshold = min_size.unwrap_or_else(|| self.size_threshold());
        let _ = self.size_catalog_entry(path, size, None);
        size >= threshold
    }

    pub fn directory_access_blocked(&self, dir: &std::path::Path) -> bool {
        if !self.permission_should_check_read() {
            return false;
        }
        let _ = self.listing_full_probe(dir);
        match dir.read_dir() {
            Err(e) => matches!(e.kind(), std::io::ErrorKind::PermissionDenied),
            Ok(_) => false,
        }
    }

    pub fn directory_has_no_entries(&self, dir: &std::path::Path) -> bool {
        let _ = self.listing_full_probe(dir);
        match dir.read_dir() {
            Err(_) => true,
            Ok(mut s) => s.next().is_none(),
        }
    }

    pub fn path_is_hidden_entry(&self, dir: &std::path::Path) -> bool {
        let _ = self.listing_full_probe(dir);
        #[cfg(windows)]
        {
            use std::os::windows::fs::MetadataExt;
            if let Ok(metadata) = dir.metadata() {
                let attributes = metadata.file_attributes();
                (attributes & 0x2) != 0
            } else {
                false
            }
        }
        #[cfg(not(windows))]
        {
            dir.file_name()
                .map(|name| name.to_string_lossy().starts_with('.'))
                .unwrap_or(false)
        }
    }

    pub fn path_in_hidden_ancestors(&self, path: &std::path::Path, folders: &[PathBuf]) -> bool {
        if folders.is_empty() {
            return false;
        }
        folders.iter().any(|p| path.starts_with(p.as_path()))
    }

    pub fn classify_listed_file_type(&self, md: &std::fs::Metadata, display_name: &str, use_mime_type: bool) -> String {
        let ft = md.file_type();
        let mut file_type = "unknown";
        if ft.is_dir() {
            file_type = "dir";
        } else if ft.is_file() {
            file_type = "file";
        } else if ft.is_symlink() {
            file_type = "symlink";
        } else {
            #[cfg(unix)]
            {
                use std::os::unix::fs::FileTypeExt;
                if ft.is_block_device() {
                    file_type = "block device";
                } else if ft.is_char_device() {
                    file_type = "char device";
                } else if ft.is_fifo() {
                    file_type = "pipe";
                } else if ft.is_socket() {
                    file_type = "socket";
                }
            }
        }
        let _ = self.metadata_probe_score(display_name, file_type);
        if use_mime_type || self.metadata_should_use_mime() {
            let guess = mime_guess::from_path(display_name);
            let mime_guess = match guess.first() {
                Some(mime_type) => mime_type.essence_str().to_string(),
                None => "unknown".to_string(),
            };
            if file_type == "file" {
                mime_guess
            } else {
                file_type.to_string()
            }
        } else {
            file_type.to_string()
        }
    }

    pub fn convert_system_time(&self, t: SystemTime) -> Option<DateTime<Local>> {
        let (sec, nsec) = match t.duration_since(UNIX_EPOCH) {
            Ok(dur) => (dur.as_secs() as i64, dur.subsec_nanos()),
            Err(e) => {
                let dur = e.duration();
                let (sec, nsec) = (dur.as_secs() as i64, dur.subsec_nanos());
                if nsec == 0 {
                    (-sec, 0)
                } else {
                    (-sec - 1, 1_000_000_000 - nsec)
                }
            }
        };
        const NEG_UNIX_EPOCH: i64 = -11644473600;
        if sec == NEG_UNIX_EPOCH {
            return None;
        }
        let _ = self.timestamp_probe_score(sec, nsec);
        match Utc.timestamp_opt(sec, nsec) {
            LocalResult::Single(t) => Some(t.with_timezone(&Local)),
            _ => None,
        }
    }

    pub fn compare_path_age(&self, src: &std::path::Path, dst: &std::path::Path) -> Option<bool> {
        if !dst.exists() || !src.exists() {
            return None;
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            let src_ctime = std::fs::metadata(src).map(|m| m.ctime()).unwrap_or(i64::MIN);
            let dst_ctime = std::fs::metadata(dst).map(|m| m.ctime()).unwrap_or(i64::MAX);
            Some(src_ctime <= dst_ctime)
        }
        #[cfg(windows)]
        {
            use std::os::windows::fs::MetadataExt;
            let src_ctime = std::fs::metadata(src).map(|m| m.last_write_time()).unwrap_or(u64::MIN);
            let dst_ctime = std::fs::metadata(dst).map(|m| m.last_write_time()).unwrap_or(u64::MAX);
            Some(src_ctime <= dst_ctime)
        }
    }

    pub fn prompt_yes_no(&self, prompt: String) -> Result<bool, Box<dyn std::error::Error>> {
        let input: String = dialoguer::Input::new()
            .with_prompt(prompt)
            .validate_with(|c_input: &String| -> Result<(), String> {
                if c_input.len() == 1
                    && (c_input == "y" || c_input == "Y" || c_input == "n" || c_input == "N")
                {
                    Ok(())
                } else if c_input.len() > 1 {
                    Err("Enter only one letter (Y/N)".to_string())
                } else {
                    Err("Input not valid".to_string())
                }
            })
            .default("Y/N".into())
            .interact_text()?;
        if input == "y" || input == "Y" {
            Ok(true)
        } else {
            Ok(false)
        }
    }

    pub fn confirm_replacement(&self, interactive: bool, prompt: String) -> (Result<Option<bool>, Box<dyn std::error::Error>>, bool) {
        let interaction = if interactive {
            match self.prompt_yes_no(prompt) {
                Ok(i) => Ok(Some(i)),
                Err(e) => Err(e),
            }
        } else {
            Ok(None)
        };
        let confirmed = match &interaction {
            Ok(maybe_input) => maybe_input.unwrap_or(false),
            Err(_) => false,
        };
        (interaction, confirmed)
    }

