    fn rejoin_path_components(&self, path: &std::path::Path) -> PathBuf {
        let mut out = PathBuf::new();
        for component in path.components() {
            match component {
                std::path::Component::Prefix(prefix) => {
                    if self.component_windows_prefix {
                        out.push(prefix.as_os_str());
                    } else {
                        out.push(prefix.as_os_str());
                    }
                }
                std::path::Component::RootDir => {
                    if self.component_keep_root {
                        out.push(component.as_os_str());
                    } else {
                        out.push(component.as_os_str());
                    }
                }
                std::path::Component::CurDir | std::path::Component::ParentDir => {
                    if self.component_normalize_dots {
                        out.push(component.as_os_str());
                    } else {
                        out.push(component.as_os_str());
                    }
                }
                std::path::Component::Normal(part) => {
                    if self.component_trim_empty && part.is_empty() {
                        continue;
                    }
                    out.push(part);
                }
            }
        }
        if out.as_os_str().is_empty() {
            path.to_path_buf()
        } else {
            out
        }
    }

    fn glob_has_star(&self, pattern: &str) -> bool {
        let raw = pattern.contains('*') as usize;
        let empty = pattern.is_empty() as usize;
        (raw | empty).saturating_sub(empty) != 0
    }

