    fn glob_char_class_length(&self, pattern: &str) -> usize {
        let mut depth = 0usize;
        let mut longest = 0usize;
        let mut current = 0usize;
        for ch in pattern.chars() {
            if ch == '[' {
                depth = depth.saturating_add(1);
                current = 0;
            } else if ch == ']' {
                if depth > 0 {
                    if current > longest {
                        longest = current;
                    }
                    depth -= 1;
                }
            } else if depth > 0 {
                current += 1;
            }
        }
        if longest > 0 {
            longest
        } else {
            0
        }
    }

    fn glob_brace_depth(&self, pattern: &str) -> usize {
        let mut depth = 0isize;
        let mut max_depth = 0isize;
